#!/usr/bin/env python3
import collections
import re
import subprocess
import sys


TARGET_CHROM = "chrX"
TARGET_POS = 154398500  # 1-based
MIN_BASE_QUALITY = 13
EXCLUDED_FLAGS = 4 | 256 | 512 | 1024 | 2048


def target_query_index(aln_start, cigar):
    """Return the zero-based query index aligned to TARGET_POS, or None."""
    ref_pos = aln_start
    query_pos = 0
    for length_text, op in re.findall(r"(\d+)([MIDNSHP=X])", cigar):
        length = int(length_text)
        if op in "M=X":
            if ref_pos <= TARGET_POS < ref_pos + length:
                return query_pos + (TARGET_POS - ref_pos)
            ref_pos += length
            query_pos += length
        elif op in "DN":
            if ref_pos <= TARGET_POS < ref_pos + length:
                return None
            ref_pos += length
        elif op in "IS":
            query_pos += length
        elif op in "HP":
            pass
    return None


def main(bam_path, output_path):
    observations = []
    process = subprocess.Popen(
        ["samtools", "view", bam_path],
        stdout=subprocess.PIPE,

